import{_ as l,l as i,o as e,c as A,v as r,p as d,x as t,d as n,i as s,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"VeRA","description":"","frontmatter":{"title":"VeRA","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vera.md","filePath":"llm/vera.md","lastUpdated":1789023840000}'),p={name:"llm/vera.md"};function B(h,a,_,E,R,c){const o=i("Mermaid");return e(),A("div",null,[a[1]||(a[1]=r('<h1 id="vera" tabindex="-1">VeRA <a class="header-anchor" href="#vera" aria-label="Permalink to &quot;VeRA&quot;">​</a></h1><div class="epigraph"><p>低秩矩阵可以冻结成共享随机投影，只学两条缩放向量；每任务参数降到与宽度同阶，而不是与 $r(d_{\\mathrm{in}}+d_{\\mathrm{out}})$ 同阶。</p><footer>—— Kopiczko、Blankevoort、Asano，VeRA: Vector-based Random Matrix Adaptation，ICLR 2024</footer></div><p><a href="/llm/rslora">rsLoRA</a>稳住了「可变的 \\(A,B\\)」在不同秩下的尺度。下一条极限是：<strong>还要不要学 \\(A,B\\)</strong>。Kopiczko 等人的 VeRA 把 \\(A,B\\) 固定为随机矩阵（层间甚至可共享），只训练向量 \\(d\\) 与 \\(b\\) 去缩放行与列。缺口是：LoRA 的存储随任务 × 秩 × 层膨胀，服务成千上万适配器时，\\(A,B\\) 本身成为瓶颈。VeRA 用随机特征换参数量。不把梯度投影（<a href="/llm/galore">下一课 GaLore</a>）混进适配器公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/lora">LoRA</a> 每层每任务存 \\(A\\in\\mathbb{R}^{r\\times d_{\\mathrm{in}}}\\)、\\(B\\in\\mathbb{R}^{d_{\\mathrm{out}}\\times r}\\)。\\(r=16\\)、宽 4096、几十层、注意力四投影，单任务已数百万参数；一万客户就要一万份。许多任务的更新也许能共用同一组随机方向，只在这些方向上的增益不同——类似随机特征 / 冻结投影。问题是：冻结随机 \\(A,B\\) 是否还够指令适应；以及随机矩阵如何在层之间共享才不崩。</p><p>若不够，VeRA 会表现为学不动，需要退回可训练 LoRA 或加 \\(r\\)。若够，每任务只存两条向量，合并与分发成本接近「偏置级」。</p><h3 id="随机投影不是压缩已学适配器" tabindex="-1">随机投影不是压缩已学适配器 <a class="header-anchor" href="#随机投影不是压缩已学适配器" aria-label="Permalink to &quot;随机投影不是压缩已学适配器&quot;">​</a></h3><p>VeRA 不是把训好的 LoRA 做 SVD 再丢掉。它从一开始就不训 \\(A,B\\)。与 AdaLoRA 动态秩、rsLoRA 改 \\(\\gamma\\) 都不同。它押的是：适应发生在随机低秩子空间的对角缩放上。</p><p><span class="marginnote">论文在 GLUE 与指令设定上显示：参数远少于 LoRA 时仍可接近。主张是参数效率的另一端，不是普遍替代满秩 LoRA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一层的增量写成对角缩放夹随机低秩：</p> \\[\\Delta W = \\Lambda_b\\, B\\, \\Lambda_d\\, A, \\]<p>其中 \\(A,B\\) 随机冻结，\\(\\Lambda_d,\\Lambda_b\\) 由可训练向量 \\(d,b\\) 生成对角。\\(A,B\\) 可在层间共享同一份随机种子，以进一步压缩；每层仍有自己的 \\(d,b\\)。初始化使初始 \\(\\Delta W\\) 接近零（向量从合适常数起），以免第一步打歪 \\(W_0\\)。缩放与学习率仍要按<a href="/llm/lora-vs-full-lr">适配器逻辑</a>取，通常大于全参。</p>',13)),(e(),d(m,null,{default:t(()=>[s(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%20x%22%5D%20--%3E%20A%5B%22%E5%86%BB%E7%BB%93%E9%9A%8F%E6%9C%BA%20A%22%5D%0A%20%20A%20--%3E%20D%5B%22%E5%8F%AF%E8%AE%AD%E7%BB%83%E5%AF%B9%E8%A7%92%20d%22%5D%0A%20%20D%20--%3E%20B%5B%22%E5%86%BB%E7%BB%93%E9%9A%8F%E6%9C%BA%20B%22%5D%0A%20%20B%20--%3E%20BB%5B%22%E5%8F%AF%E8%AE%AD%E7%BB%83%E5%AF%B9%E8%A7%92%20b%22%5D%0A%20%20W0%5B%22%E5%86%BB%E7%BB%93%20W0%22%5D%20--%3E%20S%5B%22%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20BB%20--%3E%20S%0A%20%20S%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>训练与 SFT 契约不变：<a href="/llm/chat-template">模板</a>、<a href="/llm/response-only-loss">仅回复</a>。推理可把 \\(\\Delta W\\) 显式物化后合并，或保留向量在线乘；共享随机矩阵要在服务端存一份，任务只加载向量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可训练自由度约为每层 \\(r+d_{\\mathrm{out}}\\) 量级（视实现），远小于 \\(r(d_{\\mathrm{in}}+d_{\\mathrm{out}})\\)。表达力上限是：只能沿随机列空间做对角重加权，不能旋转到数据决定的子空间——LoRA 的 \\(A,B\\) 能把子空间本身学出来。任务接近「在固定方向上增益」时差距小；需要发现新方向时差距大。这与<a href="/llm/lora-intrinsic-rank">内在秩</a>课将讨论的「适应维数」一致：若内在维很小且与随机投影重叠良好，VeRA 够用。</p><p>共享层间 \\(A,B\\) 等于假设各层可用同一组随机方向，层间差异全由 \\(d,b\\) 承担。层间适应模式差很多时，应取消共享或回到 LoRA。</p><p><span class="marginnote">rsLoRA 的 1/√r 针对可训练因子的方差。VeRA 的随机矩阵尺度由初始化方差决定，应单独设定，使冻结投影的输出与基座激活同量级。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>领域适配要改很多方向（<a href="/llm/domain-adaptation-ft">DAPT</a>）时 VeRA 往往不够。RFT 多轮自举需要容量，也不优先 VeRA。它适合：任务极多、每任务数据少、以风格/路由为主。随机种子必须与检查点一起版本化，否则向量无法对上 \\(A,B\\)。量化基座（QLoRA）可与 VeRA 叠加：基座 4-bit，向量 16-bit。</p><p>不要与 NVIDIA 芯片名「Vera」混淆：本课只指 Vector-based Random Matrix Adaptation。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VeRA 冻结随机 \\(A,B\\)，只学对角缩放向量，每任务参数接近向量级。</li><li>表达力低于可训练 LoRA：子空间不能学，只能在随机方向上增益。</li><li>层间共享随机矩阵进一步压缩，也进一步绑死层间几何。</li><li>适合海量轻量任务；不适合满秩领域改写。</li><li>随机种子是契约，必须与向量一起存。</li><li>出处：Kopiczko 等，VeRA，ICLR 2024。</li></ul>',10))])}const u=l(p,[["render",B]]);export{f as __pageData,u as default};
